WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_trv_m_ratio'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '比例型相遇', 'kp-trv-m-ratio', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "比例型相遇"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心推论：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "相遇时，两人走过的路程之比 = 速度之比！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "只给出两人速度比，以及相遇点偏离中点多少米，求全长。这种题堪称秒杀神题。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心法则"}]}, {"type": "katexBlock", "attrs": {"content": "\\text{因为时间 T 一样，所以 } \\frac{S_甲}{S_乙} = \\frac{V_甲}{V_乙}"}}, {"type": "paragraph", "content": [{"type": "text", "text": "既然路程比就是速度比，我们就可以直接把整条路切成“份数”。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 甲乙相向而行，速度比 3:2。相遇点距中点 5 千米。求全长？"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "切份数：因为 V甲:V乙=3:2，所以相遇时，甲走了全长的 3 份，乙走了 2 份。全长一共是 5 份！"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "定中点：既然全长 5 份，中点就在 2.5 份的位置。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "找差值：甲走了 3 份，比中点多出了 3 - 2.5 = 0.5 份。这多出的 0.5 份，对应的就是真实的 5 千米！"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算总长：0.5 份 = 5 千米，说明 1 份 = 10 千米。全长 5 份 = 50 千米。"}]}]}]}]}$$ AS jsonb), NULL, '比例型相遇的核心考点与实战推导。', category_node.id, CAST('["数量关系", "行程问题", "比例型相遇"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_trv_m_ratio", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
